using EZapi;
using Il2Cpp;
using HarmonyLib;
using System.Text.Json;
using Il2CppInterop.Common;
using Il2CppInterop.Runtime.Runtime;

var results=new List<object>();var failures=new List<string>();
void Check(bool b,string why="assertion failed"){if(!b)throw new Exception(why);}
void Reject(Action a){try{a();}catch(ArgumentException){return;}catch(InvalidOperationException){return;}throw new Exception("expected exception");}
void Case(string name,Action a){try{a();results.Add(new{name,passed=true});}catch(Exception e){failures.Add(name+": "+e);results.Add(new{name,passed=false,error=e.Message});}}
void Reset(bool install=true){
 GameItem.MissingTagSentinel=false;Harmony.FailUnpatch=false;InventoryRuntime.Stop();Harmony.Installed.Clear();Harmony.FailPatch=false;
 Il2CppInteropUtils.Missing=false;UnityVersionHandler.Zero=false;UnityVersionHandler.Alias=false;
 GameSession.Identity=new(1,"test",1);PlayerStore.instance=new();ItemMouseDragHandler.current=null;ItemMultiSelectHandler.current=null;
 InventoryRuntime.Start();if(install)InventoryRuntime.DirectoryReady();
}
(GameGridInventory source,GameGridInventory target,GameItem item,GameItem owner) World(){Reset();var source=new GameGridInventory();var target=new GameGridInventory();var item=new GameItem();source.Add(item);var owner=new GameItem(){identifier="test.owner"};target.Owner=owner;return(source,target,item,owner);}
bool Admit(GameItem item,GameGridInventory target)=>target.MayHaveValidInventorySlot(item);

Case("all required groups installed independently",()=>{Reset();var status=HookApi.GetRuntimeStatus();Check(status.Count==6&&status.Count(x=>x.OwnerId.StartsWith("ezapi.inventory.")&&x.Ready)==3);Check(status.Single(x=>x.OwnerId=="ezapi.inventory.endpoint").Ready==false,"persistent endpoint runtime is isolated from inventory guard groups in this suite");Check(status.Single(x=>x.OwnerId=="ezapi.power.external").Ready==false,"dedicated external group is explicitly uninstalled in this suite");Check(status.Single(x=>x.OwnerId=="ezapi.items.localization").Ready==false,"item localization runtime is isolated from inventory guard groups in this suite");Check(InventoryFreezeApi.IsAvailable&&InventoryAdmissionApi.IsAvailable&&ListInventoryApi.IsAvailable);});
Case("validation rejects before directory readiness",()=>{Reset(false);Check(!HookApi.TryValidateNativeTarget(typeof(GameItem).GetMethod(nameof(GameItem.MayRemove)),out _));});
Case("validation accepts concrete generated entry",()=>{Reset();Check(HookApi.TryValidateNativeTarget(typeof(GameItem).GetMethod(nameof(GameItem.MayRemove)),out var reason)&&reason is null);});
Case("validation rejects managed method",()=>{Reset();Check(!HookApi.TryValidateNativeTarget(typeof(object).GetMethod(nameof(object.ToString)),out _));});
Case("validation rejects null",()=>{Reset();Check(!HookApi.TryValidateNativeTarget(null,out _));});
Case("validation rejects zero executable entry",()=>{Reset();UnityVersionHandler.Zero=true;Check(!HookApi.TryValidateNativeTarget(typeof(GameItem).GetMethod(nameof(GameItem.MayRemove)),out _));});
Case("validation rejects background thread",()=>{Reset();Check(Task.Run(()=>!HookApi.TryValidateNativeTarget(typeof(GameItem).GetMethod(nameof(GameItem.MayRemove)),out _)).Result);});
Case("missing generated metadata disables groups",()=>{Reset(false);Il2CppInteropUtils.Missing=true;InventoryRuntime.DirectoryReady();Check(HookApi.GetRuntimeStatus().All(x=>!x.Ready)&&!InventoryFreezeApi.IsAvailable);});
Case("patch installation failure disables groups and clears owned patches",()=>{Reset(false);Harmony.FailPatch=true;InventoryRuntime.DirectoryReady();Check(HookApi.GetRuntimeStatus().All(x=>!x.Ready)&&Harmony.Installed.Values.All(x=>x.Count==0));});
Case("native address alias disables multihook groups",()=>{Reset(false);UnityVersionHandler.Alias=true;InventoryRuntime.DirectoryReady();Check(!InventoryFreezeApi.IsAvailable&&!InventoryAdmissionApi.IsAvailable);});
Case("lost required owner invalidates readiness",()=>{Reset();var method=typeof(GameItem).GetMethod(nameof(GameItem.MayRemove))!;Harmony.Installed[method].Clear();Check(!InventoryFreezeApi.IsAvailable);});
