Case("permit rejects nested transfer and clears after exception",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Reject(()=>InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>{InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>null);return null;}));Check(!w.item.MayRemove());Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>w.target.TryFindOneValidInventorySlot(w.item))==1);});
Case("permit rejects substituted marker item",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>new(){item=new GameItem(),inventory=w.target,numTransfer=1})==0&&w.target.AcceptCalls==0);});
Case("permit rejects substituted marker inventory",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>new(){item=w.item,inventory=w.source,numTransfer=1})==0);});
Case("permit run changes invalidate before accept",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>{GameSession.Identity=new(2,"other",2);return w.target.TryFindOneValidInventorySlot(w.item);})==0);});
Case("permit disposed lease invalidates pending transfer",()=>{var w=World();var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>{lease.Dispose();return w.target.TryFindOneValidInventorySlot(w.item);})==0);Reject(()=>InventoryFreezeApi.Extend(lease,new[]{w.item}));});
Case("permit reset invalidates pending transfer",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>{InventoryRuntime.SceneChanged();return w.target.TryFindOneValidInventorySlot(w.item);})==0);});
Case("permit accepts and expels at most once",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;w.target.AcceptOverride=(m,n)=>{Check(!InventoryFreezeApi.AllowsAccept(m,n));Check(InventoryFreezeApi.AllowsExpel(w.source,w.item));Check(!InventoryFreezeApi.AllowsExpel(w.source,w.item));return 0;};Check(InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>w.target.TryFindOneValidInventorySlot(w.item))==0);});
Case("permit wrong quantity cannot consume acceptance",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;w.target.AcceptOverride=(m,n)=>{Check(!InventoryFreezeApi.AllowsAccept(m,n+1));return 0;};InventoryFreezeApi.Transfer(lease!,w.item,w.target,1,()=>w.target.TryFindOneValidInventorySlot(w.item));});
Case("permit explicit expel releases no other instance",()=>{var w=World();using var lease=InventoryFreezeApi.TryAcquire(new[]{w.item})!;Check(InventoryFreezeApi.Expel(lease!,w.item,w.source)&&w.item.parentInventory is null);Check(!w.item.MayRemove());});

InventoryRuntime.Stop();
var report=new{suite="inventory-guards",passed=results.Count-failures.Count,failed=failures.Count,cases=results,nativeRuntimeTest=false,limitations="real service/installer/prefix/postfix sources with simulated Harmony/Interop/native objects; no native detour/UI/save proof"};
Directory.CreateDirectory("work");File.WriteAllText("work/ezapi-guard-tests.json",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine(JsonSerializer.Serialize(new{report.passed,report.failed}));foreach(var failure in failures)Console.Error.WriteLine(failure);if(failures.Count>0)Environment.Exit(1);
